	update intakedastaging
	set updatedby = 'CDM-13741',
		updatedon = now(),
		jsondata = (select jsonb(jsondata) - 'General' || jsonb(json_build_object('General',(
						select jsonb(jsondata->>'General')-'Narrative' || jsonb(json_build_object('Narrative', '<p>RS Patti Simms, screener, Baltimore County CPS, 410-887-8463</p><p><br></p><p>Case head: Jessica Mattos</p><p>Father: Javon Fleming</p><p><br></p><p>Children: Amir Williams, age 7; Gianna Mattos, age 6; Julian Mattos, age 4; Noah Williams, age 2 months (SEN cocaine, open Baltimore Co.)</p><p><br></p><p>The following email was received from Baltimore County screening:</p><p><br></p><p>I didn''t get all of the demographics, but it should be in the active SEN case.&nbsp;Here is the information from my call with the reporter:</p><p><br></p><p><span style="color: rgb(34, 34, 34);">The father (Jovon Fleming, 301-437-4295), who wants to remain anonymous, called Screening on 5/26/21.&nbsp;On 5/14/21, the mother (Jessica Mattos, 8/6/90) veered over to the other side of the road and killed a woman and injured her daughter Gianna Mattos, 6/20/14 (who is now with the maternal grandmother).&nbsp;Gianna&nbsp;had a deep laceration on her leg.&nbsp;The baby (Noah) was also in the car.&nbsp;Ms. Mattos&nbsp;was reportedly under the influence of alcohol.&nbsp;The father/caller has custody of the child they share.&nbsp;He does not plan to let his&nbsp;son go to visit the mother at her house; he plans to allow her to visit at the grandmother''s house.&nbsp;Ms. Mattos just got out of the hospital from her injuries from the accident.&nbsp;Yesterday, she picked up her 4-month-old (Noah), and the baby is in her care.&nbsp;The caller is concerned about her ability to care for the baby.&nbsp;Ms. Mattos has a broken leg and a broken wrist.&nbsp;She is staying at the home of her boyfriend’s mother.&nbsp;The boyfriend/Noah''s father is incarcerated, and the grandmother is disabled.&nbsp;&nbsp;</span></p><p><br></p><p>Address:&nbsp;&nbsp;<a href="https://www.google.com/maps/search/8262+Kings+Crown+Rd.,+Pikesville,+21208?entry=gmail&amp;source=g" target="_blank" style="color: rgb(17, 85, 204);">8262 Kings Crown Rd., Pikesville, 21208</a>.</p><p><br></p><p>(SN: this following was found via Google Search which confirms the location of the accident.)</p><p><br></p><p><strong>NEWS RELEASE:</strong>&nbsp;Howard County police are investigating a two-vehicle collision on Friday in Ellicott City in which one person was killed and three people were injured.</p><p>At approximately 3:37 p.m., a 2020 Ford F-150 was traveling south on Homewood Road near Master’s Run when it crossed into oncoming traffic for an unknown reason and struck a 2019 Kia Soul head-on.</p><p>The driver and sole occupant of the Kia, 41-year-old Tiffany Reilly of Sykesville, was pronounced dead at the scene. The driver of the Ford, an adult female, and two juvenile passengers, were transported to Johns Hopkins Hospital with serious injuries.</p><p><br></p><p>The investigation into the cause of the collision is ongoing. Homewood Road in the area of Master''s Run was closed for approximately five hours.</p><p>###</p><p><br></p><p>Referral to be sent for approval on 5/27/2021.</p><p><br></p><p>Law enforcement notified of this referral on 5/26/2021.</p>') )
						from intakedastaging i 
						where intakenumber = 'I211010161768' and activeflag = 1))
					) from intakedastaging i2
					where intakenumber = 'I211010161768' and activeflag = 1)
	where intakenumber = 'I211010161768' and activeflag = 1;

